int max(int a, int b) { return a > b ? a : b; }

int main() {
    int n;
    scanf("%d", &n);
    int cards[3 * n];
    for (int i = 0; i < 3 * n; i++) {
        scanf("%d", &cards[i]);
    }

    // dp[state] = max points from current state
    // state: 5 cards (values 1..n, encoded base n+1)
    int dp[1];
    int size = 1;
    for (int i = 0; i < 5; i++) size *= (n + 1);
    int *dpArr = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) dpArr[i] = -1;

    // initial state from first 5 cards
    int initState = 0;
    for (int i = 0; i < 5; i++) {
        initState = initState * (n + 1) + cards[i];
    }
    dpArr[initState] = 0;

    int nextIdx = 5;
    for (int op = 0; op < n - 1; op++) {
        int *nextDp = (int*)malloc(size * sizeof(int));
        for (int i = 0; i < size; i++) nextDp[i] = -1;

        for (int state = 0; state < size; state++) {
            if (dpArr[state] == -1) continue;
            // decode state
            int s = state;
            int arr[5];
            for (int i = 4; i >= 0; i--) {
                arr[i] = s % (n + 1);
                s /= (n + 1);
            }

            // Try all permutations of the 5 cards
            int perm[5] = {0,1,2,3,4};
            // generate all permutations via recursion
            // we'll just do nested loops for 5! = 120
            int indices[5];
            for (indices[0]=0; indices[0]<5; indices[0]++)
            for (indices[1]=0; indices[1]<5; indices[1]++)
            if (indices[1]!=indices[0])
            for (indices[2]=0; indices[2]<5; indices[2]++)
            if (indices[2]!=indices[0] && indices[2]!=indices[1])
            for (indices[3]=0; indices[3]<5; indices[3]++)
            if (indices[3]!=indices[0] && indices[3]!=indices[1] && indices[3]!=indices[2])
            for (indices[4]=0; indices[4]<5; indices[4]++)
            if (indices[4]!=indices[0] && indices[4]!=indices[1] && indices[4]!=indices[2] && indices[4]!=indices[3]) {
                int reordered[5];
                for (int i = 0; i < 5; i++) reordered[i] = arr[indices[i]];
                // remove first 3, check if all equal
                int gain = (reordered[0] == reordered[1] && reordered[1] == reordered[2]) ? 1 : 0;
                // remaining 2 plus next card(s)
                int newArr[5];
                newArr[0] = reordered[3];
                newArr[1] = reordered[4];
                int pos = 2;
                if (nextIdx + (5 - pos) <= 3 * n) {
                    for (int k = nextIdx; k < nextIdx + (5 - pos) && k < 3*n; k++) {
                        newArr[pos++] = cards[k];
                    }
                }
                // fill rest with 0 (representing "no card")
                while (pos < 5) newArr[pos++] = 0;

                int newState = 0;
                for (int i = 0; i < 5; i++) {
                    newState = newState * (n + 1) + newArr[i];
                }
                nextDp[newState] = max(nextDp[newState], dpArr[state] + gain);
            }
        }
        free(dpArr);
        dpArr = nextDp;
        nextIdx += 2; // we consumed 3 and added 2 from deck, net -1 card from front each operation
    }

    // After n-1 operations, we have 3 cards left.
    int ans = 0;
    for (int state = 0; state < size; state++) {
        if (dpArr[state] == -1) continue;
        int s = state;
        int arr[5];
        for (int i = 4; i >= 0; i--) {
            arr[i] = s % (n + 1);
            s /= (n + 1);
        }
        if (arr[0] != 0 && arr[1] != 0 && arr[2] != 0 &&
            arr[0] == arr[1] && arr[1] == arr[2]) {
            ans = max(ans, dpArr[state] + 1);
        } else {
            ans = max(ans, dpArr[state]);
        }
    }

    printf("%d\n", ans);
    free(dpArr);
    return 0;
