typedef struct {
    int a[3];
} Triple;

static int cmp3(const void *p, const void *q) {
    int x = *(const int *)p, y = *(const int *)q;
    return (x > y) - (x < y);
}

static Triple norm3(int x, int y, int z) {
    Triple t;
    t.a[0] = x; t.a[1] = y; t.a[2] = z;
    qsort(t.a, 3, sizeof(int), cmp3);
    return t;
}

static int triple_equal(Triple x, Triple y) {
    return x.a[0] == y.a[0] && x.a[1] == y.a[1] && x.a[2] == y.a[2];
}

static int is_all_equal3(Triple t) {
    return t.a[0] == t.a[1] && t.a[1] == t.a[2];
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = 3 * N;
    int *c = (int *)malloc(sizeof(int) * M);
    for (int i = 0; i < M; i++) scanf("%d", &c[i]);

    if (N == 1) {
        int ans = (c[0] == c[1] && c[1] == c[2]) ? 1 : 0;
        printf("%d\n", ans);
        free(c);
        return 0;
    }

    /* DP over states:
       After processing i operations (0..N-1), exactly 3 cards remain at front
       from previous steps, and next unread cards start at position 3 + 3*i.
       State = multiset of these 3 remaining cards.
       Transition: combine state cards with next 3 input cards => 6 cards.
       Choose any 3 to remove; remaining 3 become next state.
       Score +1 if removed 3 are all equal.
    */

    int maxStates = 8; /* grows to at most 20 */
    Triple *states = (Triple *)malloc(sizeof(Triple) * maxStates);
    int *dp = (int *)malloc(sizeof(int) * maxStates);
    int stateCount = 1;

    states[0] = norm3(c[0], c[1], c[2]);
    dp[0] = 0;

    for (int step = 0; step < N - 1; step++) {
        int x = c[3 + 3 * step];
        int y = c[3 + 3 * step + 1];
        int z = c[3 + 3 * step + 2];

        int nextCap = stateCount * 20 + 5;
        Triple *nextStates = (Triple *)malloc(sizeof(Triple) * nextCap);
        int *nextDp = (int *)malloc(sizeof(int) * nextCap);
        int nextCount = 0;

        for (int s = 0; s < stateCount; s++) {
            int arr[6];
            arr[0] = states[s].a[0];
            arr[1] = states[s].a[1];
            arr[2] = states[s].a[2];
            arr[3] = x;
            arr[4] = y;
            arr[5] = z;

            for (int i = 0; i < 6; i++) {
                for (int j = i + 1; j < 6; j++) {
                    for (int k = j + 1; k < 6; k++) {
                        int rem[3], rr = 0;
                        int removed[3] = {arr[i], arr[j], arr[k]};
                        for (int t = 0; t < 6; t++) {
                            if (t != i && t != j && t != k) rem[rr++] = arr[t];
                        }

                        Triple nt = norm3(rem[0], rem[1], rem[2]);
                        int gain = (removed[0] == removed[1] && removed[1] == removed[2]) ? 1 : 0;
                        int val = dp[s] + gain;

                        int pos = -1;
                        for (int u = 0; u < nextCount; u++) {
                            if (triple_equal(nextStates[u], nt)) {
                                pos = u;
                                break;
                            }
                        }
                        if (pos == -1) {
                            nextStates[nextCount] = nt;
                            nextDp[nextCount] = val;
                            nextCount++;
                        } else if (val > nextDp[pos]) {
                            nextDp[pos] = val;
                        }
                    }
                }
            }
        }

        free(states);
        free(dp);
        states = nextStates;
        dp = nextDp;
        stateCount = nextCount;
    }

    int ans = 0;
    for (int s = 0; s < stateCount; s++) {
        int val = dp[s] + (is_all_equal3(states[s]) ? 1 : 0);
        if (val > ans) ans = val;
    }

    printf("%d\n", ans);

    free(states);
    free(dp);
    free(c);
    return 0;
}

