                    for(int bit=0;bit<5;bit++) if((mask>>bit&1)==1) rem[ri++]=five[bit]; else keep[ki++]=five[bit];
                    int pts=dp[a][b]+((rem[0]==rem[1]&&rem[1]==rem[2])?1:0);
                    int na=Math.min(keep[0],keep[1]),nb=Math.max(keep[0],keep[1]);
                    if(ndp[na][nb]<pts) ndp[na][nb]=pts;
                }
            }
            dp=ndp;
        }

        // final: 2 carry + 1 last card
        int last=cards[idx];
        int ans=0;
        for(int a=1;a<=N;a++) for(int b=a;b<=N;b++){
            if(dp[a][b]<0) continue;
            int pts=dp[a][b]+((a==b&&b==last)?1:0);
            ans=Math.max(ans,pts);
        }
        System.out.println(ans);
    }
}

import java.io.*;
